    "name": "回纹",
    "english": "FRET PATTERN",
    "category": "几何构成",
    "era": "新石器时代至明清持续演变",
    "meaning": "绵延不断 · 富贵长久",
    "summary": "方折回环，像一条没有尽头的线。",
    "description": "回纹由连续方折的线条回环组织而成，常见于陶器、青铜器、织物、建筑与家具边饰。它以极简的几何秩序表达“连续”与“长久”，也常作为其他纹样的边框和底纹。",
    "structure": "以方形回环为单元，通过二方连续或四方连续排列；转折处形成节奏，适合做边饰、框架与底纹。",
