    "description": "龟背纹以六边形或近似六边形的网格为基本结构，因形似龟甲而得名。它常见于器物、建筑与织物装饰，既能独立成面，也能作为其他纹样的底格，具有强烈的秩序感与延展性。",
    "structure": "以六边形为单元进行四方连续排列；通过边线共用形成无缝网格，可在网格中填入花卉、几何或文字母题。",
    "elements": [
      "几何",
      "网格",
      "四方连续"
    ],
