    "summary": "一条线回环穿插，没有起点也没有终点。",
    "description": "盘长纹以回环穿插的线条构成连续不断的结形，常与“八吉祥”等吉祥观念相联系。它的视觉魅力来自线条之间的压叠、穿插与闭合关系，既有几何秩序，也有流动感。",
