    "meaning": "江山永固 · 福山寿海",
    "summary": "波浪与山崖，构成一片微缩的山海。",
    "description": "海水江崖纹以层叠波涛、山崖和祥云组合而成，常见于明清服饰、织物与器物。它把自然山水压缩为具有象征意义的装饰图式，在有限的边饰或下摆空间中形成辽阔感。",
    "structure": "以水平波浪为底，山崖为视觉重心，祥云与浪花作为穿插元素；通过层层叠加形成前后空间与流动节奏。",
